#!/usr/bin/env node
import { spawn } from "node:child_process";
import { access } from "node:fs/promises";
import { constants } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const packageRoot = resolve(__dirname, "..");
const binaryPath = resolve(packageRoot, "vendor", binaryName());

try {
  await access(binaryPath, constants.X_OK);
} catch {
  console.error(
    [
      `markdown-exit-ratex: no bundled RaTeX binary for ${process.platform}/${process.arch}.`,
      `Expected: ${binaryPath}`,
      "Install or publish a package build that includes this platform, or pass cli.command to markdown-exit-ratex.",
    ].join("\n"),
  );
  process.exit(1);
}

const child = spawn(binaryPath, process.argv.slice(2), {
  stdio: "inherit",
});

child.on("error", (error) => {
  console.error(error.message);
  process.exit(1);
});

child.on("exit", (code, signal) => {
  if (signal) {
    process.kill(process.pid, signal);
    return;
  }
  process.exit(code ?? 1);
});

function binaryName() {
  const platform = normalizePlatform(process.platform);
  const arch = normalizeArch(process.arch);
  const extension = process.platform === "win32" ? ".exe" : "";
  return `ratex-render-svg-${platform}-${arch}${extension}`;
}

function normalizePlatform(platform) {
  switch (platform) {
    case "darwin":
      return "darwin";
    case "linux":
      return "linux";
    case "win32":
      return "windows";
    default:
      return platform;
  }
}

function normalizeArch(arch) {
  switch (arch) {
    case "x64":
      return "x64";
    case "arm64":
      return "arm64";
    default:
      return arch;
  }
}
